<?php
final class AccountSecurityMail {
 public static function render(string $title,string $message,?string $code=null,bool $recovery=false):string {
  $app=require __DIR__.'/../../config/app.php';$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=$app['base_url'].($recovery?'/auth/forgot_password.php':'/dashboard/layout.php?page=profile');
  return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f2f6fa;font-family:Arial,sans-serif;color:#28485f"><table role="presentation" style="max-width:580px;width:100%;margin:25px auto;background:#fff;border:1px solid #dbe5ee;border-collapse:collapse"><tr><td style="padding:24px;background:#163269;color:#fff"><img src="cid:srcb-school-seal" width="48" height="48" alt="SRCB" style="vertical-align:middle;margin-right:12px"><strong>SRCB Guidance · Account security</strong></td></tr><tr><td style="padding:30px"><h1 style="font-size:23px">'.$e($title).'</h1><p style="line-height:1.8">'.$e($message).'</p>'.($code!==null?'<p style="text-align:center;font-size:34px;font-weight:bold;letter-spacing:9px;padding:18px;background:#eef7f5;border-radius:8px;color:#176e63">'.$e($code).'</p><p style="font-size:13px;line-height:1.7">This code expires in 10 minutes and can be used once. Enter it on the page where you requested it. Never share your code or password.</p>':'').'<p style="margin-top:25px"><a href="'.$e($url).'" style="display:inline-block;background:#176e63;color:white;padding:12px 17px;border-radius:6px;text-decoration:none;font-weight:bold">'.($recovery?'Open password recovery':'Review account security').'</a></p></td></tr><tr><td style="padding:20px 30px;border-top:1px solid #dbe5ee;color:#637e90;font-size:12px;line-height:1.7">If you did not request this change, contact the Guidance Office. An unused verification code does not change your account.<br>St. Rita’s College of Balingasag · Guidance Office</td></tr></table></body></html>';
 }
}
